UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites arithmétiques","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites arithmétiques : raison, terme général $u_n = u_0 + nr$, somme par Gauss $S = (n+1)(u_0 + u_n)/2$.","exercices":[{"number":1,"title_fr":"Identifier et calculer","points":5,"preamble_fr":"On considère la suite $(u_n)$ telle que $u_0 = 3$ et $u_{n+1} = u_n + 5$.","questions":[{"number":1,"stem_fr":"Justifier que $(u_n)$ est arithmétique et donner sa raison.","points":2,"solution":{"steps":[{"text_fr":"Par définition d''une suite arithmétique : $u_{n+1} - u_n = r$ constant. Ici $u_{n+1} - u_n = (u_n + 5) - u_n = 5$."},{"text_fr":"La différence entre deux termes consécutifs est **constante et vaut 5**. Donc $(u_n)$ est arithmétique de **raison $r = 5$**."}],"final_answer_fr":"$r = 5$"}},{"number":2,"stem_fr":"Donner l''expression de $u_n$ en fonction de $n$.","points":1,"solution":{"steps":[{"text_fr":"**Terme général** : $u_n = u_0 + nr = 3 + 5n$."}],"final_answer_fr":"$u_n = 3 + 5n$"}},{"number":3,"stem_fr":"Calculer $u_{10}$, $u_{20}$ et $u_{50}$.","points":2,"solution":{"steps":[{"text_fr":"Application directe : $u_{10} = 3 + 50 = 53$."},{"text_fr":"$u_{20} = 3 + 100 = 103$ ; $u_{50} = 3 + 250 = 253$.","tip_fr":"L''expression explicite permet de calculer n''importe quel terme directement, sans énumérer les précédents."}],"final_answer_fr":"$u_{10} = 53$, $u_{20} = 103$, $u_{50} = 253$"}}]},{"number":2,"title_fr":"Sommes","points":5,"preamble_fr":"On utilise la suite $(u_n)$ de l''Exercice 1.","questions":[{"number":1,"stem_fr":"Calculer la somme $S = u_0 + u_1 + \\dots + u_{10}$ (11 termes).","points":3,"solution":{"steps":[{"text_fr":"**Formule de Gauss** : $S = (\\text{nombre de termes}) \\times \\dfrac{\\text{premier} + \\text{dernier}}{2}$."},{"text_fr":"Ici 11 termes, $u_0 = 3$, $u_{10} = 53$. Donc $S = 11 \\times (3 + 53)/2 = 11 \\times 28 = 308$."}],"final_answer_fr":"$S = 308$"}},{"number":2,"stem_fr":"Calculer $1 + 2 + 3 + \\dots + 100$.","points":2,"solution":{"steps":[{"text_fr":"Suite arithmétique de premier terme 1, raison 1, 100 termes."},{"text_fr":"**Formule** : $S_{100} = 100 \\times (1 + 100)/2 = 5050$. Anecdote : Gauss l''aurait calculée à l''âge de 9 ans, à la surprise de son instituteur."}],"final_answer_fr":"$S = 5050$"}}]},{"number":3,"title_fr":"Sens de variation","points":5,"preamble_fr":"Soit $(v_n)$ arithmétique de premier terme $v_0 = 100$ et raison $r = -3$.","questions":[{"number":1,"stem_fr":"Donner l''expression de $v_n$ et étudier le sens de variation.","points":3,"solution":{"steps":[{"text_fr":"$v_n = 100 - 3n$. Calcul : $v_{n+1} - v_n = -3 < 0$. La suite est **strictement décroissante**."},{"text_fr":"**Règle générale** : suite arithmétique avec $r > 0$ → croissante ; $r < 0$ → décroissante ; $r = 0$ → constante."}],"final_answer_fr":"$v_n = 100 - 3n$, décroissante"}},{"number":2,"stem_fr":"À partir de quel rang $n$ a-t-on $v_n < 0$ ?","points":2,"solution":{"steps":[{"text_fr":"$v_n < 0 \\iff 100 - 3n < 0 \\iff n > 100/3 \\approx 33{,}3$."},{"text_fr":"Donc à partir de $n = 34$ : $v_{34} = 100 - 102 = -2 < 0$ ✓. Avant : $v_{33} = 100 - 99 = 1 > 0$."}],"final_answer_fr":"$n \\ge 34$"}}]},{"number":4,"title_fr":"Problème — escaliers","points":5,"preamble_fr":"Un escalier comporte 50 marches. La première marche a une hauteur de 18 cm. Chaque marche suivante est 0,2 cm plus haute que la précédente.","questions":[{"number":1,"stem_fr":"Quelle est la hauteur de la 25ème marche ?","points":2,"solution":{"steps":[{"text_fr":"Suite arithmétique de $u_1 = 18$, $r = 0{,}2$. Terme général : $u_n = u_1 + (n-1) r = 18 + 0{,}2(n-1)$."},{"text_fr":"Pour la 25ème marche : $u_{25} = 18 + 0{,}2 \\times 24 = 18 + 4{,}8 = 22{,}8\\,cm$."}],"final_answer_fr":"$u_{25} = 22{,}8$ cm"}},{"number":2,"stem_fr":"Quelle est la hauteur totale de l''escalier ?","points":3,"solution":{"steps":[{"text_fr":"Hauteur totale = somme de toutes les hauteurs. $u_{50} = 18 + 0{,}2 \\times 49 = 27{,}8\\,cm$."},{"text_fr":"Somme : $H = 50 \\times (18 + 27{,}8)/2 = 50 \\times 22{,}9 = 1145\\,cm = 11{,}45\\,m$."},{"text_fr":"Vérification : si toutes les marches faisaient 22,9 cm (la moyenne), la hauteur serait $50 \\times 22{,}9 = 1145\\,cm$ ✓."}],"final_answer_fr":"$H = 11{,}45$ m"}}]}]}'::jsonb WHERE code = 'arithmetic_seq';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Suites géométriques","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Suites géométriques : raison $q$, terme général $u_n = u_0 q^n$, somme $S = u_0 (1 - q^{n+1})/(1-q)$, limites selon $|q|$.","exercices":[{"number":1,"title_fr":"Identification","points":5,"preamble_fr":"Soit $(u_n)$ telle que $u_0 = 2$ et $u_{n+1} = 3 u_n$.","questions":[{"number":1,"stem_fr":"Montrer que $(u_n)$ est géométrique et donner la raison.","points":2,"solution":{"steps":[{"text_fr":"Définition d''une suite géométrique : $u_{n+1}/u_n = q$ constant. Ici $u_{n+1}/u_n = 3$."},{"text_fr":"Donc $(u_n)$ est géométrique de **raison $q = 3$** (multiplication par 3 à chaque étape)."}],"final_answer_fr":"$q = 3$"}},{"number":2,"stem_fr":"Donner $u_n$ en fonction de $n$ et calculer $u_5$, $u_{10}$.","points":3,"solution":{"steps":[{"text_fr":"Terme général : $u_n = u_0 q^n = 2 \\cdot 3^n$."},{"text_fr":"$u_5 = 2 \\times 243 = 486$ ; $u_{10} = 2 \\times 59049 = 118098$.","tip_fr":"Croissance exponentielle pour $|q| > 1$ — chaque terme est $q$ fois le précédent."}],"final_answer_fr":"$u_n = 2 \\cdot 3^n$, $u_5 = 486$, $u_{10} = 118098$"}}]},{"number":2,"title_fr":"Sommes","points":5,"preamble_fr":"Avec la suite $u_n = 2 \\cdot 3^n$.","questions":[{"number":1,"stem_fr":"Calculer $S = u_0 + u_1 + \\dots + u_5$ (6 termes).","points":3,"solution":{"steps":[{"text_fr":"**Formule** : $S = u_0 \\dfrac{1 - q^{n+1}}{1 - q}$ pour $n+1$ termes."},{"text_fr":"Ici 6 termes, $u_0 = 2$, $q = 3$. $S = 2 \\dfrac{1 - 3^6}{1 - 3} = 2 \\dfrac{1 - 729}{-2} = 2 \\times 364 = 728$."}],"final_answer_fr":"$S = 728$"}},{"number":2,"stem_fr":"Limite de la somme infinie $1 + 1/2 + 1/4 + 1/8 + \\dots$","points":2,"solution":{"steps":[{"text_fr":"Suite géométrique $u_0 = 1$, $q = 1/2$, $|q| < 1$ → somme infinie converge."},{"text_fr":"Formule : $S_\\infty = u_0/(1 - q) = 1/(1 - 1/2) = 2$.","tip_fr":"Pour $|q| < 1$, $q^n \\to 0$ et $S_n \\to u_0/(1-q)$ — c''est le paradoxe de Zénon résolu."}],"final_answer_fr":"$S_\\infty = 2$"}}]},{"number":3,"title_fr":"Comportement à l''infini","points":5,"preamble_fr":"Étudier la limite de la suite $(u_n)$ selon la valeur de $q$ pour $u_n = u_0 q^n$ avec $u_0 > 0$.","questions":[{"number":1,"stem_fr":"Donner la limite $\\lim u_n$ selon les 4 cas : $q > 1$, $q = 1$, $|q| < 1$, $q \\le -1$.","points":5,"solution":{"steps":[{"text_fr":"**$q > 1$** : $q^n \\to +\\infty$, donc $u_n \\to +\\infty$. Croissance exponentielle."},{"text_fr":"**$q = 1$** : $u_n = u_0$ constant. Limite : $u_0$."},{"text_fr":"**$|q| < 1$** (c-à-d $-1 < q < 1$) : $q^n \\to 0$, donc $u_n \\to 0$. Décroissance vers 0."},{"text_fr":"**$q = -1$** : $u_n$ alterne $\\pm u_0$ → **pas de limite**."},{"text_fr":"**$q < -1$** : oscillations divergentes ($|u_n| \\to +\\infty$ avec alternance de signe) → **pas de limite**.","tip_fr":"Mémo : la limite d''une suite géométrique dépend uniquement de la position de $q$ par rapport à 1 et -1."}]}}]},{"number":4,"title_fr":"Application — capital à intérêts composés","points":5,"preamble_fr":"Un capital $C_0 = 1000\\,€$ est placé à un taux annuel de 5%. Soit $C_n$ le capital après $n$ ans.","questions":[{"number":1,"stem_fr":"Justifier que $(C_n)$ est géométrique. Donner sa raison.","points":2,"solution":{"steps":[{"text_fr":"Chaque année, le capital est multiplié par $1{,}05$ (capital initial + 5% d''intérêts). Donc $C_{n+1} = 1{,}05 \\times C_n$."},{"text_fr":"Géométrique de raison $q = 1{,}05$."}],"final_answer_fr":"$q = 1{,}05$"}},{"number":2,"stem_fr":"Calculer $C_{10}$ et $C_{30}$.","points":2,"solution":{"steps":[{"text_fr":"$C_n = C_0 \\times 1{,}05^n = 1000 \\times 1{,}05^n$."},{"text_fr":"$C_{10} = 1000 \\times 1{,}629 \\approx 1629\\,€$ ; $C_{30} = 1000 \\times 4{,}322 \\approx 4322\\,€$."},{"text_fr":"**Insight** : en 30 ans à 5%, le capital plus que quadruple. C''est le pouvoir des intérêts composés (vs intérêts simples qui donneraient 1000 + 30×50 = 2500 €)."}],"final_answer_fr":"$C_{10} \\approx 1629$ €, $C_{30} \\approx 4322$ €"}},{"number":3,"stem_fr":"Après combien d''années le capital aura-t-il doublé ?","points":1,"solution":{"steps":[{"text_fr":"Résoudre $1{,}05^n = 2 \\iff n = \\ln 2/\\ln 1{,}05 \\approx 0{,}693/0{,}0488 \\approx 14{,}2\\,\\text{ans}$."},{"text_fr":"Donc le capital double en environ **14 ans** au taux de 5%. Règle approximative : ''doublement = 72/taux %'' (ici 72/5 = 14,4, très proche).","tip_fr":"La ''règle de 72'' est très utilisée en finance : à taux r% par an, doublement en ~72/r années."}],"final_answer_fr":"$n \\approx 14$ ans"}}]}]}'::jsonb WHERE code = 'geometric_seq';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Convergence des suites","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Convergence, limite, théorème des gendarmes, monotonie + bornes, opérations sur les limites.","exercices":[{"number":1,"title_fr":"Limites usuelles","points":5,"preamble_fr":"Calculer les limites suivantes.","questions":[{"number":1,"stem_fr":"$\\lim_{n \\to \\infty} 1/n$, $1/n^2$, $1/\\sqrt{n}$.","points":2,"solution":{"steps":[{"text_fr":"**Règle générale** : pour tout $\\alpha > 0$, $\\lim 1/n^\\alpha = 0$."},{"text_fr":"Application : les 3 limites valent **0**. Plus $\\alpha$ est grand, plus la décroissance est rapide."}],"final_answer_fr":"Toutes valent 0"}},{"number":2,"stem_fr":"$\\lim_{n \\to \\infty} \\dfrac{2n + 1}{n + 3}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $\\infty/\\infty$. Diviser haut et bas par $n$ : $\\dfrac{2 + 1/n}{1 + 3/n} \\to \\dfrac{2}{1} = 2$."},{"text_fr":"**Règle** : pour un quotient de polynômes de même degré, limite = rapport des coefficients dominants."}],"final_answer_fr":"$\\lim = 2$"}},{"number":3,"stem_fr":"$\\lim_{n \\to \\infty} \\sqrt{n+1} - \\sqrt{n}$.","points":1,"solution":{"steps":[{"text_fr":"Forme $\\infty - \\infty$. **Astuce de la quantité conjuguée** : multiplier par $(\\sqrt{n+1} + \\sqrt{n})/(\\sqrt{n+1} + \\sqrt{n})$."},{"text_fr":"$\\sqrt{n+1} - \\sqrt{n} = \\dfrac{(n+1) - n}{\\sqrt{n+1} + \\sqrt{n}} = \\dfrac{1}{\\sqrt{n+1} + \\sqrt{n}} \\to 0$."}],"final_answer_fr":"$\\lim = 0$"}}]},{"number":2,"title_fr":"Théorème des gendarmes","points":5,"preamble_fr":"Soit $u_n = \\dfrac{\\sin(n)}{n}$ pour $n \\ge 1$.","questions":[{"number":1,"stem_fr":"Encadrer $u_n$.","points":2,"solution":{"steps":[{"text_fr":"$-1 \\le \\sin(n) \\le 1$. Diviser par $n > 0$ : $-1/n \\le \\sin(n)/n \\le 1/n$."}],"final_answer_fr":"$-1/n \\le u_n \\le 1/n$"}},{"number":2,"stem_fr":"En déduire la limite.","points":3,"solution":{"steps":[{"text_fr":"$\\lim -1/n = 0$ et $\\lim 1/n = 0$."},{"text_fr":"Par le **théorème des gendarmes**, $u_n$ est encadrée par deux suites qui tendent toutes deux vers 0, donc $\\lim u_n = 0$.","tip_fr":"Note : $\\sin(n)$ n''a PAS de limite, mais $\\sin(n)/n$ converge grâce à la décroissance de $1/n$."}],"final_answer_fr":"$\\lim u_n = 0$"}}]},{"number":3,"title_fr":"Convergence par monotonie","points":5,"preamble_fr":"Soit $(u_n)$ définie par $u_0 = 1$ et $u_{n+1} = \\sqrt{2 + u_n}$.","questions":[{"number":1,"stem_fr":"Étude de $(u_n)$.","points":4,"subparts":[{"letter":"a","stem_fr":"Montrer par récurrence que $1 \\le u_n \\le 2$.","points":2,"solution":{"steps":[{"text_fr":"**Initialisation** : $u_0 = 1$ vérifie $1 \\le 1 \\le 2$ ✓."},{"text_fr":"**Hérédité** : si $1 \\le u_n \\le 2$, alors $3 \\le 2 + u_n \\le 4$, donc $\\sqrt 3 \\le \\sqrt{2 + u_n} \\le 2$. Comme $\\sqrt 3 > 1$ : $1 \\le u_{n+1} \\le 2$ ✓."},{"text_fr":"Conclusion : pour tout $n$, $1 \\le u_n \\le 2$. La suite est **bornée**."}]}},{"letter":"b","stem_fr":"Montrer que $(u_n)$ est croissante.","points":2,"solution":{"steps":[{"text_fr":"On veut $u_{n+1} \\ge u_n$, soit $\\sqrt{2 + u_n} \\ge u_n$. Élever au carré (tous positifs) : $2 + u_n \\ge u_n^2 \\iff u_n^2 - u_n - 2 \\le 0 \\iff (u_n - 2)(u_n + 1) \\le 0$."},{"text_fr":"Sur $[1, 2]$ : $u_n - 2 \\le 0$ et $u_n + 1 > 0$ → produit $\\le 0$ ✓. Donc $u_{n+1} \\ge u_n$ : croissante."}]}}]},{"number":2,"stem_fr":"En déduire que $(u_n)$ converge. Calculer sa limite.","points":1,"solution":{"steps":[{"text_fr":"Suite croissante et majorée (par 2) → **convergente** par théorème de la limite monotone."},{"text_fr":"Limite $L$ : passage à la limite dans $u_{n+1} = \\sqrt{2 + u_n}$ donne $L = \\sqrt{2 + L}$. Carré : $L^2 = L + 2 \\iff (L-2)(L+1) = 0$. Avec $L \\in [1, 2]$ : $L = 2$."}],"final_answer_fr":"$L = 2$"}}]},{"number":4,"title_fr":"Opérations sur les limites","points":5,"preamble_fr":"Soient $u_n = (n^2 + 1)/n$ et $v_n = (3n - 1)/(n + 2)$. Calculer $\\lim u_n$, $\\lim v_n$, $\\lim u_n + v_n$, $\\lim u_n v_n$.","questions":[{"number":1,"stem_fr":"Calculer chaque limite.","points":5,"solution":{"steps":[{"text_fr":"$u_n = n + 1/n \\to +\\infty$."},{"text_fr":"$v_n = (3n - 1)/(n + 2) \\to 3$ (mêmes degrés, rapport des dominants)."},{"text_fr":"**Somme** : $\\lim (u_n + v_n) = +\\infty + 3 = +\\infty$."},{"text_fr":"**Produit** : $\\lim (u_n v_n) = +\\infty \\times 3 = +\\infty$.","tip_fr":"Opérations sur les limites : (+\\infty) + fini = +\\infty ; (+\\infty) × fini > 0 = +\\infty ; (+\\infty) × 0 ou (+\\infty) - (+\\infty) = formes indéterminées (cas à étudier)."}],"final_answer_fr":"$\\lim u_n = +\\infty$, $\\lim v_n = 3$, somme et produit $= +\\infty$"}}]}]}'::jsonb WHERE code = 'seq_convergence';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Limites de fonctions","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Limite en un point, à l''infini, formes indéterminées, factorisation, quantités conjuguées.","exercices":[{"number":1,"title_fr":"Calcul direct","points":4,"preamble_fr":"Calculer les limites suivantes.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 1}(x^2 + 3x - 2)$.","points":1,"solution":{"steps":[{"text_fr":"Polynôme continu partout. Substitution directe : $1 + 3 - 2 = 2$."}],"final_answer_fr":"$\\lim = 2$"}},{"number":2,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{x^2 - 4}{x - 2}$.","points":1,"solution":{"steps":[{"text_fr":"Substitution directe possible : $(0 - 4)/(0 - 2) = -4/-2 = 2$."}],"final_answer_fr":"$\\lim = 2$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 2} \\dfrac{x^2 - 4}{x - 2}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $0/0$ — factoriser : $x^2 - 4 = (x-2)(x+2)$. Donc $\\dfrac{x^2-4}{x-2} = x + 2$ pour $x \\ne 2$."},{"text_fr":"$\\lim_{x \\to 2}(x+2) = 4$."}],"final_answer_fr":"$\\lim = 4$"}}]},{"number":2,"title_fr":"Limites à l''infini","points":5,"preamble_fr":"Calculer ces limites.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{3x^2 - x}{x^2 + 5}$.","points":2,"solution":{"steps":[{"text_fr":"Quotient de polynômes de **même degré 2**. Rapport des coefficients dominants : $3/1 = 3$."}],"final_answer_fr":"$\\lim = 3$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{x + 1}{x^2}$.","points":1,"solution":{"steps":[{"text_fr":"Numérateur degré 1, dénominateur degré 2 — dénominateur l''emporte. Limite = 0."}],"final_answer_fr":"$\\lim = 0$"}},{"number":3,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{x^3 + 1}{x}$.","points":1,"solution":{"steps":[{"text_fr":"Numérateur degré 3, dénominateur degré 1 — numérateur l''emporte. $\\dfrac{x^3 + 1}{x} = x^2 + 1/x \\to +\\infty$."}],"final_answer_fr":"$\\lim = +\\infty$"}},{"number":4,"stem_fr":"$\\lim_{x \\to -\\infty}\\sqrt{x^2 + 1} + x$.","points":1,"solution":{"steps":[{"text_fr":"Forme $+\\infty - \\infty$. Quantité conjuguée : multiplier par $(\\sqrt{x^2+1} - x)/(\\sqrt{x^2+1} - x)$."},{"text_fr":"On obtient $\\dfrac{1}{\\sqrt{x^2+1} - x}$. Pour $x \\to -\\infty$, $-x \\to +\\infty$, donc dénominateur $\\to +\\infty$, fraction $\\to 0$."}],"final_answer_fr":"$\\lim = 0$"}}]},{"number":3,"title_fr":"Limites latérales","points":5,"preamble_fr":"On considère $f(x) = \\dfrac{1}{x}$.","questions":[{"number":1,"stem_fr":"Calculer $\\lim_{x \\to 0^+} f$ et $\\lim_{x \\to 0^-} f$.","points":3,"solution":{"steps":[{"text_fr":"$x \\to 0^+$ : $x > 0$ très petit, donc $1/x \\to +\\infty$."},{"text_fr":"$x \\to 0^-$ : $x < 0$ très petit, donc $1/x \\to -\\infty$."},{"text_fr":"Limites latérales différentes → **pas de limite en 0**. La courbe a une asymptote verticale en $x = 0$."}],"final_answer_fr":"$\\lim_{0^+} = +\\infty$, $\\lim_{0^-} = -\\infty$"}},{"number":2,"stem_fr":"Calculer $\\lim_{x \\to \\pm\\infty} f(x)$.","points":2,"solution":{"steps":[{"text_fr":"À $\\pm\\infty$ : $1/x \\to 0$. La courbe a une asymptote horizontale $y = 0$."},{"text_fr":"**Résumé** : la courbe de $1/x$ a deux branches (hyperbole), avec asymptotes $y = 0$ et $x = 0$."}],"final_answer_fr":"$\\lim = 0$ aux deux bornes"}}]},{"number":4,"title_fr":"Asymptote oblique","points":6,"preamble_fr":"Soit $f(x) = \\dfrac{x^2 + 1}{x - 1}$ définie sur $\\mathbb{R} \\setminus \\{1\\}$.","questions":[{"number":1,"stem_fr":"Effectuer la division euclidienne et écrire $f(x) = ax + b + \\dfrac{c}{x - 1}$.","points":3,"solution":{"steps":[{"text_fr":"Division : $x^2 + 1 = (x - 1) \\cdot x + (x + 1) = (x - 1)(x + 1) + 2$."},{"text_fr":"Donc $f(x) = x + 1 + \\dfrac{2}{x - 1}$."}],"final_answer_fr":"$f(x) = x + 1 + \\dfrac{2}{x-1}$"}},{"number":2,"stem_fr":"En déduire l''asymptote oblique de la courbe en $\\pm\\infty$.","points":3,"solution":{"steps":[{"text_fr":"Quand $x \\to \\pm\\infty$ : $\\dfrac{2}{x-1} \\to 0$, donc $f(x) - (x + 1) \\to 0$."},{"text_fr":"La courbe $y = f(x)$ admet la droite $y = x + 1$ pour **asymptote oblique** en $\\pm\\infty$.","tip_fr":"Asymptote oblique : on prend la partie polynômiale après division euclidienne. Le reste tend vers 0."}],"final_answer_fr":"$y = x + 1$ asymptote oblique"}}]}]}'::jsonb WHERE code = 'limit_def';
UPDATE public.skills SET exam_paper = '{"version":1,"title_fr":"Épreuve type — Calcul de limites avancé","subtitle_fr":"4 exercices · 1h30 · sur 20 points","duration_minutes":90,"total_points":20,"intro_fr":"Techniques avancées : factorisation, conjugué, taux d''accroissement, croissances comparées $\\ln/\\exp/x^n$.","exercices":[{"number":1,"title_fr":"Formes 0/0 par factorisation","points":5,"preamble_fr":"Calculer les limites.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 3} \\dfrac{x^2 - 9}{x - 3}$.","points":2,"solution":{"steps":[{"text_fr":"Forme $0/0$. Factoriser : $x^2 - 9 = (x-3)(x+3)$."},{"text_fr":"$\\dfrac{(x-3)(x+3)}{x-3} = x + 3 \\to 6$ quand $x \\to 3$."}],"final_answer_fr":"$\\lim = 6$"}},{"number":2,"stem_fr":"$\\lim_{x \\to 1} \\dfrac{x^3 - 1}{x^2 - 1}$.","points":3,"solution":{"steps":[{"text_fr":"Forme $0/0$. Numérateur : $x^3 - 1 = (x-1)(x^2 + x + 1)$. Dénominateur : $x^2 - 1 = (x-1)(x+1)$."},{"text_fr":"Fraction : $\\dfrac{(x-1)(x^2+x+1)}{(x-1)(x+1)} = \\dfrac{x^2+x+1}{x+1}$ (pour $x \\ne 1$)."},{"text_fr":"Limite en 1 : $\\dfrac{3}{2} = 1{,}5$."}],"final_answer_fr":"$\\lim = 3/2$"}}]},{"number":2,"title_fr":"Quantité conjuguée","points":5,"preamble_fr":"Calculer.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{\\sqrt{1 + x} - 1}{x}$.","points":3,"solution":{"steps":[{"text_fr":"Forme $0/0$. Multiplier haut et bas par la quantité conjuguée $\\sqrt{1+x} + 1$."},{"text_fr":"$\\dfrac{(\\sqrt{1+x} - 1)(\\sqrt{1+x} + 1)}{x(\\sqrt{1+x} + 1)} = \\dfrac{(1+x) - 1}{x(\\sqrt{1+x} + 1)} = \\dfrac{x}{x(\\sqrt{1+x} + 1)} = \\dfrac{1}{\\sqrt{1+x} + 1}$."},{"text_fr":"Limite en 0 : $\\dfrac{1}{1 + 1} = 1/2$.","tip_fr":"La quantité conjuguée $a - b$ multipliée par $a + b$ donne $a^2 - b^2$ — fait disparaître les racines carrées."}],"final_answer_fr":"$\\lim = 1/2$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty}\\sqrt{x^2 + x} - x$.","points":2,"solution":{"steps":[{"text_fr":"Forme $\\infty - \\infty$. Conjuguée : multiplier par $(\\sqrt{x^2+x} + x)/(\\sqrt{x^2+x} + x)$."},{"text_fr":"Numérateur : $x^2 + x - x^2 = x$. Dénominateur : $\\sqrt{x^2+x} + x \\sim 2x$ à l''infini."},{"text_fr":"Donc fraction $\\sim x/(2x) = 1/2$. Limite = $1/2$."}],"final_answer_fr":"$\\lim = 1/2$"}}]},{"number":3,"title_fr":"Taux d''accroissement","points":5,"preamble_fr":"Reconnaître un taux d''accroissement pour calculer.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{\\sin x}{x}$.","points":2,"solution":{"steps":[{"text_fr":"C''est $\\dfrac{\\sin x - \\sin 0}{x - 0}$ = taux d''accroissement de $\\sin$ entre 0 et $x$. Limite = $\\sin''(0) = \\cos 0 = 1$."},{"text_fr":"**Limite usuelle** : $\\lim_{x \\to 0} \\dfrac{\\sin x}{x} = 1$. À mémoriser absolument."}],"final_answer_fr":"$\\lim = 1$"}},{"number":2,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{e^x - 1}{x}$.","points":2,"solution":{"steps":[{"text_fr":"Taux d''accroissement de $\\exp$ en 0 : limite = $\\exp''(0) = e^0 = 1$.","tip_fr":"Limites usuelles : $\\lim_{0} \\dfrac{\\sin x}{x} = 1$, $\\lim_{0} \\dfrac{e^x - 1}{x} = 1$, $\\lim_{0} \\dfrac{\\ln(1+x)}{x} = 1$."}],"final_answer_fr":"$\\lim = 1$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 0} \\dfrac{\\ln(1 + x)}{x}$.","points":1,"solution":{"steps":[{"text_fr":"Taux d''accroissement de $\\ln$ en 1 (avec changement de variable) : $\\ln(1+x) = \\ln(1+x) - \\ln(1)$, dérivée en 1 = $1/1 = 1$."}],"final_answer_fr":"$\\lim = 1$"}}]},{"number":4,"title_fr":"Croissances comparées","points":5,"preamble_fr":"Calculer les limites.","questions":[{"number":1,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{\\ln x}{x}$ et $\\dfrac{\\ln x}{x^2}$.","points":2,"solution":{"steps":[{"text_fr":"**Théorème** : à l''infini, toute puissance positive de $x$ l''emporte sur $\\ln x$. $\\lim \\dfrac{\\ln x}{x^\\alpha} = 0$ pour tout $\\alpha > 0$."},{"text_fr":"Les deux limites valent **0**."}],"final_answer_fr":"$\\lim = 0$"}},{"number":2,"stem_fr":"$\\lim_{x \\to +\\infty} \\dfrac{e^x}{x^{10}}$.","points":2,"solution":{"steps":[{"text_fr":"**Théorème** : à l''infini, l''exponentielle l''emporte sur toute puissance. $\\lim \\dfrac{e^x}{x^n} = +\\infty$ pour tout $n$."},{"text_fr":"Donc $\\lim = +\\infty$. Hiérarchie : $\\exp \\gg x^n \\gg \\ln$ à l''infini.","tip_fr":"Cette hiérarchie est universelle — elle décide qui ''gagne'' dans les formes indéterminées $\\infty/\\infty$ ou $\\infty \\cdot 0$."}],"final_answer_fr":"$\\lim = +\\infty$"}},{"number":3,"stem_fr":"$\\lim_{x \\to 0^+} x \\ln x$.","points":1,"solution":{"steps":[{"text_fr":"Forme $0 \\cdot (-\\infty)$. Changement de variable $u = 1/x$ : $x \\ln x = (1/u) \\ln(1/u) = -\\ln(u)/u \\to 0$ quand $u \\to +\\infty$."},{"text_fr":"Donc $\\lim_{0^+} x \\ln x = 0$. Limite usuelle."}],"final_answer_fr":"$\\lim = 0$"}}]}]}'::jsonb WHERE code = 'limit_calc';

